// Package hints turns what the portal already shows about a broken object
// (a pod's STATUS, a health finding's rule) into diagnosis hints: what the
// symptom means, read-only commands to check it, and the usual causes. The
// text comes from hints.json, generated by scripts/gen-hints.py from the
// Kubernetes study notes. The package only returns text. Nothing here runs a
// command or talks to a cluster.
package hints

import (
	_ "embed"
	"encoding/json"
	"regexp"
	"strconv"
	"strings"
)

//go:embed hints.json
var catalogueJSON []byte

// Entry is one catalogue entry.
type Entry struct {
	Slug    string   `json:"slug"`
	Trigger string   `json:"trigger"`
	Meaning string   `json:"meaning"`
	Check   []string `json:"check"`
	Causes  []string `json:"causes"`
	Notes   []string `json:"notes"`
}

// Hint is an Entry for one object: the commands have the real names in them.
// Note titles are plain text; the notes are private, so there is no link.
type Hint struct {
	Slug    string   `json:"slug"`
	Meaning string   `json:"meaning"`
	Check   []string `json:"check"`
	Causes  []string `json:"causes"`
	Notes   []string `json:"notes"`
}

// Signals is what the caller already knows about one object.
type Signals struct {
	// Kind is "Pod", "Node", "Service", "Deployment", "StatefulSet" or
	// "PersistentVolumeClaim". Empty means Pod.
	Kind      string
	Namespace string // empty for a node
	Name      string
	// Status is what the portal already shows: a pod's STATUS column
	// ("CrashLoopBackOff"), or the graph status of another object ("2/3
	// ready", "Pending", "no pods match selector").
	Status   string
	NotReady bool     // a pod with fewer ready containers than containers
	Missing  bool     // something refers to this object, but it does not exist
	Rules    []string // ids of health findings about the object
	// Optional names from the pod row, used to fill commands.
	Node          string
	Container     string
	InitContainer string
}

// Kinds lists the object kinds Match understands.
var Kinds = []string{"Pod", "Node", "Service", "Deployment", "StatefulSet", "PersistentVolumeClaim"}
var catalogue = mustLoad()

func mustLoad() map[string]Entry {
	var es []Entry
	if err := json.Unmarshal(catalogueJSON, &es); err != nil {
		panic("hints: bad hints.json: " + err.Error())
	}
	m := make(map[string]Entry, len(es))
	for _, e := range es {
		m[e.Slug] = e
	}
	return m
}

// Catalogue returns every entry, for tests and tooling.
func Catalogue() map[string]Entry { return catalogue }

// Wired lists the slugs Match can return. The others have no detectable
// trigger from the signals above and are not offered.
func Wired() []string {
	set := map[string]bool{}
	for _, s := range statusSlugs {
		set[s] = true
	}
	for _, s := range ruleSlugs {
		set[s] = true
	}
	set["pod-running-not-ready"] = true
	set["pod-init-container-stuck"] = true
	for _, x := range []string{
		"service-no-ready-endpoints", "ingress-backend-misconfigured",
		"deploy-rollout-stuck-old-pods-serving", "deploy-unavailable",
		"statefulset-ordered-ready-blocked", "pvc-pending",
	} {
		set[x] = true
	}
	out := make([]string, 0, len(set))
	for s := range set {
		out = append(out, s)
	}
	return out
}

var statusSlugs = map[string]string{
	"Pending":                    "pod-pending-unschedulable",
	"ContainerCreating":          "pod-containercreating-stuck",
	"ImagePullBackOff":           "pod-image-pull-failure",
	"ErrImagePull":               "pod-image-pull-failure",
	"CrashLoopBackOff":           "pod-crashloopbackoff",
	"OOMKilled":                  "container-oomkilled",
	"Evicted":                    "pod-evicted",
	"CreateContainerConfigError": "container-config-error",
	"CreateContainerError":       "container-config-error",
	"Unknown":                    "statefulset-pod-stuck-unknown-terminating",
	"Terminating":                "statefulset-pod-stuck-unknown-terminating",
}

var ruleSlugs = map[string]string{
	"pod.image-pull":        "pod-image-pull-failure",
	"pod.no-memory-limit":   "pod-qos-class-risk",
	"node.not-ready":        "node-notready",
	"node.pressure.cpu":     "node-pressure",
	"node.pressure.io":      "node-pressure",
	"node.pressure.memory":  "node-pressure",
	"node.disk.eviction":    "node-pressure",
	"node.imagefs.eviction": "node-pressure",
}

var readyRe = regexp.MustCompile(`^(\d+)/(\d+) ready$`)

// notFullyReady reads "2/3 ready" from the graph status: have < want.
func notFullyReady(status string) (have, want int, ok bool) {
	m := readyRe.FindStringSubmatch(status)
	if m == nil {
		return 0, 0, false
	}
	have, _ = strconv.Atoi(m[1])
	want, _ = strconv.Atoi(m[2])
	return have, want, have < want
}

// podStatus turns the graph's pod status ("Pending (Unschedulable)",
// "CrashLoopBackOff (OOMKilled)", "Running, not ready") into the kubectl
// words the matcher knows. oom reports the OOMKilled suffix.
func podStatus(st string) (status string, notReady, oom bool) {
	if st == "Running, not ready" {
		return "Running", true, false
	}
	if i := strings.Index(st, " ("); i > 0 && strings.HasSuffix(st, ")") {
		oom = st[i+2:len(st)-1] == "OOMKilled"
		return st[:i], false, oom
	}
	return st, false, false
}

// Match returns the hints for the signals, most specific first. It returns
// nothing for a healthy object.
func Match(s Signals) []Hint {
	var slugs []string
	add := func(slug string) {
		for _, x := range slugs {
			if x == slug {
				return
			}
		}
		slugs = append(slugs, slug)
	}
	switch s.Kind {
	case "Pod", "":
		st, nr, oom := podStatus(s.Status)
		s.NotReady = s.NotReady || nr
		if oom {
			add("container-oomkilled")
		}
		if rest, ok := strings.CutPrefix(st, "Init:"); ok {
			if slug, ok := statusSlugs[rest]; ok {
				add(slug)
			} else {
				add("pod-init-container-stuck")
			}
		} else if st == "PodInitializing" {
			add("pod-init-container-stuck")
		} else if slug, ok := statusSlugs[st]; ok {
			add(slug)
		} else if st == "Running" && s.NotReady {
			add("pod-running-not-ready")
		}
	case "Service":
		if s.Missing {
			add("ingress-backend-misconfigured")
		}
		if s.Status == "no pods match selector" {
			add("service-no-ready-endpoints")
		}
	case "Deployment":
		if have, want, bad := notFullyReady(s.Status); bad {
			if have == 0 && want > 0 {
				add("deploy-unavailable")
			}
			add("deploy-rollout-stuck-old-pods-serving")
		}
	case "StatefulSet":
		if _, _, bad := notFullyReady(s.Status); bad {
			add("statefulset-ordered-ready-blocked")
		}
	case "PersistentVolumeClaim":
		if s.Status == "Pending" {
			add("pvc-pending")
		}
	}
	for _, r := range s.Rules {
		if slug, ok := ruleSlugs[r]; ok {
			add(slug)
		}
	}
	var out []Hint
	for _, slug := range slugs {
		if e, ok := catalogue[slug]; ok {
			out = append(out, fill(e, s))
		}
	}
	return out
}

// NameOK reports whether s is safe to put in a command: a Kubernetes name.
var nameRe = regexp.MustCompile(`^[a-z0-9]([-a-z0-9.]*[a-z0-9])?$`)

func NameOK(s string) bool { return len(s) <= 253 && nameRe.MatchString(s) }

var placeholderRe = regexp.MustCompile(`<([a-z][a-z-]*)>`)

// known returns the placeholders the signals can fill, with their values.
func known(s Signals) map[string]string {
	m := map[string]string{}
	set := func(v string, names ...string) {
		if v == "" {
			return
		}
		for _, n := range names {
			m[n] = v
		}
	}
	switch s.Kind {
	case "Node":
		set(s.Name, "node", "name")
	case "Service":
		set(s.Name, "svc", "service", "name")
	case "Deployment":
		set(s.Name, "deploy", "name")
	case "StatefulSet":
		set(s.Name, "sts", "name")
	case "PersistentVolumeClaim":
		set(s.Name, "pvc", "name")
	default:
		set(s.Name, "pod")
		set(s.Node, "node")
		set(s.Container, "container")
		set(s.InitContainer, "init-container")
	}
	set(s.Namespace, "ns", "namespace")
	return m
}

// fill puts the real names into the commands. A placeholder the signals
// cannot fill never stays in a command as <name>: pasted into a shell, < and
// > are redirections. It becomes a shell variable ("$CONTAINER") and the
// command is preceded by a line that sets it (CONTAINER=CHANGE_ME), so the
// user edits one visible value and a pasted command can only fail, not
// redirect.
func fill(e Entry, s Signals) Hint {
	vals := known(s)
	h := Hint{Slug: e.Slug, Meaning: e.Meaning, Causes: e.Causes, Notes: e.Notes}
	declared := map[string]bool{}
	for _, c := range e.Check {
		var vars []string
		out := placeholderRe.ReplaceAllStringFunc(c, func(p string) string {
			n := p[1 : len(p)-1]
			if v, ok := vals[n]; ok {
				return v
			}
			v := strings.ToUpper(strings.ReplaceAll(n, "-", "_"))
			if !declared[v] {
				declared[v] = true
				vars = append(vars, v)
			}
			return `"$` + v + `"`
		})
		for _, v := range vars {
			h.Check = append(h.Check, v+"=CHANGE_ME")
		}
		h.Check = append(h.Check, out)
	}
	return h
}
